INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(11337, 'plPL', 'Wezwanie do boju: Oko Cyklonu', 'Walka z Hordą nie zna granic, $N. Nawet w Rubieży spory terytorialne i dawne nienawiści wystarczą, by przechylić szalę na stronę wojny.$B$BUdaj się do Oka Cyklonu i dopilnuj, by Przymierze zwyciężyło w Rubieży tak samo, jak zwyciężyło w Azeroth.', 'Wygraj bitwę w Oku Cyklonu i wróć do generała brygady Przymierza w dowolnej stolicy Przymierza, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo w Oku Cyklonu', 'Wróć do generała brygady Przymierza.', '', '', '', '', 0),
(14179, 'plPL', 'Wezwanie do boju: Oko Cyklonu', 'Walka z Hordą nie zna granic, $N. Nawet w Rubieży spory terytorialne i dawne nienawiści wystarczą, by przechylić szalę na stronę wojny.$B$BUdaj się do Oka Cyklonu i dopilnuj, by Przymierze zwyciężyło w Rubieży tak samo, jak zwyciężyło w Azeroth.', 'Wygraj bitwę w Oku Cyklonu i wróć do generała brygady Przymierza w dowolnej stolicy Przymierza, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo w Oku Cyklonu', 'Wróć do generała brygady Przymierza.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(11337, 'plPL', 'Jesteśmy o krok bliżej całkowitego zwycięstwa nad Hordą. Nie możemy pozwolić, by wróg zdobył przyczółek w tym ani w żadnym innym świecie.', 0),
(11341, 'plPL', 'Przynosisz nam wszystkim chlubę, $N. Musimy pokazać wrogowi, że będziemy z nim walczyć wszędzie, gdzie go znajdziemy.', 0),
(14179, 'plPL', 'Jesteśmy o krok bliżej całkowitego zwycięstwa nad Hordą. Nie możemy pozwolić, by wróg zdobył przyczółek w tym ani w żadnym innym świecie.', 0),
(14182, 'plPL', 'Przynosisz nam wszystkim chlubę, $N. Musimy pokazać wrogowi, że będziemy z nim walczyć wszędzie, gdzie go znajdziemy.', 0);
